content:
{
  "initial_state": "arrival_and_relaxation",
  "states": [
    {
      "id": "arrival_and_relaxation",
      "description": "Person arrives home, adjusts climate, retrieves a drink, and settles on the sofa.",
      "rules": [
        {
          "trigger": "air conditioner · off, indoor temperature 29°C",
          "action": "Operate the air conditioner: turn on at 26°C."
        },
        {
          "trigger": "Person enters through the front door",
          "action": "Operate the refrigerator: open door."
        },
        {
          "trigger": "Person enters through the front door",
          "action": "Take the cola out of the refrigerator and place it next to the person."
        },
        {
          "trigger": "refrigerator · door has been open for 1 minute",
          "action": "Operate the refrigerator: close door."
        }
      ],
      "next": [
        {
          "to": "laundry_management",
          "on": "washing machine · cycle finished"
        }
      ]
    },
    {
      "id": "laundry_management",
      "description": "Washing machine cycle completes and laundry is transferred to the dryer.",
      "rules": [
        {
          "trigger": "washing machine · cycle finished",
          "action": "Operate the washing machine: open door."
        },
        {
          "trigger": "washing machine · cycle finished",
          "action": "Take the laundry out of the washing machine and place it next to the person."
        },
        {
          "trigger": "washing machine · cycle finished",
          "action": "Operate the dryer: open door."
        },
        {
          "trigger": "washing machine · cycle finished",
          "action": "Operate the dryer: close door."
        },
        {
          "trigger": "washing machine · cycle finished",
          "action": "Operate the dryer: start."
        }
      ],
      "next": [
        {
          "to": "kitchen_cleanup",
          "on": "dryer · cycle started"
        }
      ]
    },
    {
      "id": "kitchen_cleanup",
      "description": "Person consumes milk and cleans up the empty cup using the dishwasher.",
      "rules": [
        {
          "trigger": "A cup is on the kitchen counter",
          "action": "Operate the dishwasher: open door."
        },
        {
          "trigger": "A cup is on the kitchen counter",
          "action": "Put the cup from the kitchen counter into the dishwasher."
        },
        {
          "trigger": "A cup is on the kitchen counter",
          "action": "Operate the dishwasher: close door."
        }
      ],
      "next": []
    }
  ]
}
